const items = $input.all();
const today = new Date().toISOString().slice(0, 10);

return items.map(item => {
  const { symbol, sector, status } = item.json;
  const prompt = `Today is ${today}. Search the web for news about ${symbol} stock (${sector}) from TODAY ONLY.\nReturn up to 3 significant news items from today (earnings, partnerships, FDA decisions, analyst upgrades/downgrades, regulatory news, major price catalysts).\nIf no news from today exists, respond exactly: NO_NEWS_TODAY\nFormat: concise bullet points only. No analysis.`;
  const body = {
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 512,
    tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: 3 }],
    messages: [{ role: 'user', content: prompt }]
  };
  return { json: { symbol, sector, status, body } };
});

const data = $json;
const prep = $('Prepare Haiku Request').item.json;
const symbol = prep.symbol;
const sector = prep.sector;
const status = prep.status;

let text = '';
if (data.content && Array.isArray(data.content)) {
  for (const block of data.content) {
    if (block.type === 'text') text += block.text;
  }
}
if (data.error) text = 'NO_NEWS_TODAY';

return [{ json: { symbol, sector, status, rawNews: text.trim() || 'NO_NEWS_TODAY' } }];

const news = {};
for (const item of $input.all()) {
  news[item.json.symbol] = item.json.rawNews;
}
return [{ json: { news } }];

const data = $json;
const allNews = $('Aggregate All News').first().json.news || {};
const newTickers = Array.isArray(data.new) ? data.new : Object.keys(allNews);
const skipTickers = Array.isArray(data.skip) ? data.skip : [];
const newCount = newTickers.length;
return [{ json: { newTickers, skipTickers, newCount, allNews } }];

const { newTickers, allNews } = $json;
const newNews = {};
for (const sym of (newTickers || [])) {
  newNews[sym] = allNews[sym] || '';
}
return [{ json: { news: newNews } }];

const data = $input.first().json;
let warrenText = '';
if (typeof data.synthesis === 'string') {
  warrenText = data.synthesis.trim();
} else if (data.error) {
  warrenText = "Erreur de synthèse Warren : " + data.error;
}
if (!warrenText) {
  warrenText = "Aucune actualité pertinente aujourd'hui.";
}
return [{ json: { warrenText } }];

const warrenText = $input.first().json.warrenText || "Aucune actualité pertinente aujourd'hui.";
const date = new Date().toLocaleDateString('fr-FR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

function mdToHtml(md) {
  return md
    .replace(/^#{1,3} (.+)$/gm, (m, t) => '<h3 style="color:#1a1a2e;font-size:18px;margin:20px 0 8px">' + t + '</h3>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/^> (.+)$/gm, '<blockquote style="border-left:3px solid #ccc;padding-left:10px;color:#555;margin:6px 0">$1</blockquote>')
    .replace(/^- (.+)$/gm, '<li>$1</li>')
    .replace(/(<li>.*<\/li>\n?)+/g, s => '<ul style="margin:4px 0 8px 20px">' + s + '</ul>')
    .replace(/^---$/gm, '<hr style="border:none;border-top:1px solid #eee;margin:16px 0">')
    .replace(/\n{2,}/g, '</p><p style="margin:8px 0">')
    .replace(/\n/g, '<br>');
}

const htmlBody = '<html><body style="font-family:Arial,sans-serif;max-width:820px;margin:auto;padding:24px;color:#222">'
  + '<h1 style="color:#1a1a2e;font-size:24px;border-bottom:3px solid #e94560;padding-bottom:10px">📈 Veille Boursière — ' + date + '</h1>'
  + '<div style="margin-top:20px"><p style="margin:8px 0">' + mdToHtml(warrenText) + '</p></div>'
  + '<p style="color:#bbb;font-size:11px;margin-top:32px;border-top:1px solid #eee;padding-top:10px">Synthèse Warren 🦉 via n8n + OpenClaw</p>'
  + '</body></html>';

return [{ json: {
  htmlBody,
  subject: '📈 Veille Boursière — ' + new Date().toLocaleDateString('fr-FR')
}}];

const warrenText = $input.first().json.warrenText;
const text = (warrenText && warrenText.trim())
  ? warrenText.trim()
  : "Aucune actualité pertinente aujourd'hui. Bonne journée.";
return [{ json: { text } }];

const text = $input.first().json.text || "Aucune actualité pertinente aujourd'hui.";
const MAX = 4000;

if (text.length <= MAX) {
  return [{ json: { chunk: text } }];
}

const paragraphs = text.split(/\n\n+/);
const chunks = [];
let current = '';

for (const para of paragraphs) {
  const candidate = current ? current + '\n\n' + para : para;
  if (candidate.length > MAX) {
    if (current) chunks.push(current);
    current = para.length > MAX ? para.slice(0, MAX) : para;
  } else {
    current = candidate;
  }
}
if (current) chunks.push(current);

return chunks.map((chunk, i) => ({
  json: { chunk: chunks.length > 1 ? '_(' + (i+1) + '/' + chunks.length + ')_\n\n' + chunk : chunk }
}));
